def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_def = 0
    bad = 0
    soft = 0
    dd = 0

    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_def += 1
        if m == 'C' and o == 'D':
            if i == 0 or history[i - 1][0] == 'C':
                bad += 1
        elif m == 'D':
            if o == 'C':
                soft += 1
            else:
                dd += 1

    start = max(0, n - 10)
    recent_opp_def = 0
    recent_bad = 0
    recent_soft = 0

    for i in range(start, n):
        m, o = history[i]
        if o == 'D':
            recent_opp_def += 1
        if m == 'C' and o == 'D':
            if i == 0 or history[i - 1][0] == 'C':
                recent_bad += 1
        if m == 'D' and o == 'C':
            recent_soft += 1

    opp_def_streak = 0
    idx = n - 1
    while idx >= 0:
        if history[idx][1] == 'D':
            opp_def_streak += 1
            idx -= 1
        else:
            break

    opp_coop_streak = 0
    idx = n - 1
    while idx >= 0:
        if history[idx][1] == 'C':
            opp_coop_streak += 1
            idx -= 1
        else:
            break

    mutual_cc_streak = 0
    idx = n - 1
    while idx >= 0:
        if history[idx][0] == 'C' and history[idx][1] == 'C':
            mutual_cc_streak += 1
            idx -= 1
        else:
            break

    soft_streak = 0
    idx = n - 1
    while idx >= 0:
        if history[idx][0] == 'D' and history[idx][1] == 'C':
            soft_streak += 1
            idx -= 1
        else:
            break

    defect_rate = opp_def / n

    hard = False
    if bad >= 3:
        hard = True
    if recent_bad >= 2 and n >= 6:
        hard = True
    if opp_def_streak >= 5:
        hard = True
    if n >= 20 and opp_def * 13 > n * 8 and recent_bad >= 1:
        hard = True
    if n >= 40 and opp_def * 2 > n and recent_bad >= 2:
        hard = True

    if hard:
        if opp_coop_streak >= 5 and recent_bad == 0 and rng.random() < 0.35:
            return 'C'
        if opp_coop_streak >= 10:
            return 'C'
        return 'D'

    if opp_last == 'D':
        unprovoked = (my_last == 'C' and (n == 1 or history[-2][0] == 'C'))

        if unprovoked:
            if bad <= 1 and opp_def * 10 < n and rng.random() < 0.12:
                return 'C'
            return 'D'

        if opp_def_streak <= 3 and recent_opp_def <= 4:
            return 'C'
        if recent_opp_def <= 2 and bad <= 1:
            return 'C'
        if defect_rate < 0.45 and rng.random() < 0.3:
            return 'C'

        return 'D'

    if my_last == 'D':
        if soft_streak >= 2:
            return 'D'

        if recent_soft >= 3 and defect_rate < 0.5 and bad <= 2:
            return 'D'

        denom = soft + dd
        if denom >= 3 and soft * 3 >= denom * 2:
            if bad <= 1 and defect_rate < 0.45:
                return 'D'

        if defect_rate < 0.25 and recent_bad == 0 and rng.random() < 0.2:
            return 'D'

        return 'C'

    if n >= 80 and mutual_cc_streak >= 5 and defect_rate < 0.08 and rng.random() < 0.06:
        return 'D'

    if n >= 50 and mutual_cc_streak >= 10 and defect_rate < 0.04 and rng.random() < 0.02:
        return 'D'

    return 'C'
